// DeploymentResourcesProbeQuery is a parent query with one or more existence probes against
// deployment_resources, combined with AND. Build it with DeploymentHavingResources or
// DeploymentNotHavingResources and extend it with AndHaving/AndNotHaving.
type DeploymentResourcesProbeQuery struct {
	q deployment.Query
	p []deploymentResourcesProbeQueryProbe
}

type deploymentResourcesProbeQueryProbe struct {
	c   resource.Query
	neg bool
}

// DeploymentHavingResources narrows q to rows with at least one matching deployment_resources row —
// the filtered semi-join, in one statement. The child predicates are
// typed by the child's own package; ids and values meet only here.
func DeploymentHavingResources(q deployment.Query, ps ...resource.Pred) DeploymentResourcesProbeQuery {
	return DeploymentResourcesProbeQuery{q: q}.AndHaving(ps...)
}

// DeploymentNotHavingResources narrows q to rows with NO matching deployment_resources row — the
// filtered anti-join.
//
// Read the predicates carefully: this is "has no deployment_resources row matching
// these", not "has a deployment_resources row that does not match". With no predicates
// at all it is "has none". The two questions have different answers
// whenever a parent has several children, and SQL spells them the same
// way round.
func DeploymentNotHavingResources(q deployment.Query, ps ...resource.Pred) DeploymentResourcesProbeQuery {
	return DeploymentResourcesProbeQuery{q: q}.AndNotHaving(ps...)
}

// AndHaving adds another EXISTS probe against deployment_resources, ANDed with the
// ones already there.
func (h DeploymentResourcesProbeQuery) AndHaving(ps ...resource.Pred) DeploymentResourcesProbeQuery {
	return h.probe(false, ps...)
}

// AndNotHaving adds a NOT EXISTS probe against deployment_resources. This is how
// "has one of these but none of those" is one statement:
//
//	DeploymentHavingResources(q, bought).AndNotHaving(alsoBought)
func (h DeploymentResourcesProbeQuery) AndNotHaving(ps ...resource.Pred) DeploymentResourcesProbeQuery {
	return h.probe(true, ps...)
}

func (h DeploymentResourcesProbeQuery) probe(neg bool, ps ...resource.Pred) DeploymentResourcesProbeQuery {
	// Copied rather than appended in place: a composer is a value, and
	// two chains branching from one base must not share a backing array.
	p := make([]deploymentResourcesProbeQueryProbe, len(h.p), len(h.p)+1)
	copy(p, h.p)
	h.p = append(p, deploymentResourcesProbeQueryProbe{c: resource.New().Unordered().Where(ps...), neg: neg})
	return h
}

var deploymentResourcesProbeQueryLowering = func() runtime.Lowering {
	lw := deployment.Lowering()
	parentFrag := lw.Frag
	lw.Frag = func(op, col uint32) runtime.Frag {
		if col >= runtime.ChildColBase {
			return resource.FragOf(op, col-runtime.ChildColBase)
		}
		return parentFrag(op, col)
	}
	// The token's relation id picks the header: 0 positive, 1 negated.
	// Both probes are the same relation, so only the polarity varies.
	lw.Exists = func(rel uint32) string {
		if rel == 1 {
			return "NOT EXISTS (SELECT 1 FROM \"deployment_resources\" AS \"_storm_e\" WHERE \"_storm_e\".\"deployment_id\" = \"deployments\".\"id\" AND \"_storm_e\".\"deleted_at\" IS NULL"
		}
		return "EXISTS (SELECT 1 FROM \"deployment_resources\" AS \"_storm_e\" WHERE \"_storm_e\".\"deployment_id\" = \"deployments\".\"id\" AND \"_storm_e\".\"deleted_at\" IS NULL"
	}
	return lw
}()

var deploymentResourcesProbeQueryCache = runtime.NewTreeCache()

func (h DeploymentResourcesProbeQuery) stmt(count bool) (*runtime.Stmt, []runtime.Tok) {
	var buf [44]runtime.Tok
	toks := h.q.PredToks(buf[:0])
	stack := 0
	if len(toks) > 0 {
		stack = 1
	}
	for _, pr := range h.p {
		child := pr.c.PredToks(nil)
		toks = runtime.OffsetCols(toks, child, runtime.ChildColBase)
		arity := uint32(0)
		if len(child) > 0 {
			arity = 1 // the child stream reduces to one stack entry
		}
		rel := uint32(0)
		if pr.neg {
			rel = 1
		}
		toks = append(toks, runtime.MakeExists(rel, arity))
		stack++
	}
	if stack > 1 {
		toks = append(toks, runtime.MakeGroup(runtime.KAnd, uint32(stack)))
	}
	if !count {
		toks = h.q.OrderToks(toks)
	}
	sel, cnt, limitSfx := deployment.StmtPieces()
	prefix, suffix := sel, limitSfx
	if count {
		prefix, suffix = cnt, ""
	}
	if st := deploymentResourcesProbeQueryCache.Get(toks); st != nil {
		return st, toks
	}
	return deploymentResourcesProbeQueryCache.Put(toks, runtime.SpliceTree(prefix, toks, deploymentResourcesProbeQueryLowering, suffix)), toks
}

// bind returns the arguments in STREAM order: parent predicates, then
// each probe's, then the parent's paging. Each probe takes its own
// binder — bindPreds resets the arenas it fills, so two probes sharing
// one binder would have the second silently overwrite the first.
func (h DeploymentResourcesProbeQuery) bind(pb *deployment.Binder, paging bool) ([]any, []*resource.Binder) {
	args := h.q.BindPreds(pb, nil)
	cbs := make([]*resource.Binder, 0, len(h.p))
	for _, pr := range h.p {
		cb := resource.GetBinder()
		cbs = append(cbs, cb)
		args = pr.c.BindPreds(cb, args)
	}
	if paging {
		args = h.q.BindPaging(pb, args)
	}
	return args, cbs
}

func (h DeploymentResourcesProbeQuery) err() error {
	if err := h.q.Err(); err != nil {
		return err
	}
	for _, pr := range h.p {
		if err := pr.c.Err(); err != nil {
			return err
		}
	}
	return nil
}

// All runs the composed statement.
func (h DeploymentResourcesProbeQuery) All(ctx context.Context, ex runtime.Executor) ([]deployment.Row, error) {
	if err := h.err(); err != nil {
		return nil, err
	}
	st, _ := h.stmt(false)
	if st.Err != nil {
		return nil, st.Err
	}
	pb := deployment.GetBinder()
	defer deployment.PutBinder(pb)
	args, cbs := h.bind(pb, true)
	defer func() {
		for _, cb := range cbs {
			resource.PutBinder(cb)
		}
	}()
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var sl runtime.Slab
	var out []deployment.Row
	for rows.Next() {
		out = append(out, deployment.Row{})
		if err := deployment.Scan(rows.RawValues(), &out[len(out)-1], &sl); err != nil {
			return nil, err
		}
	}
	return out, rows.Err()
}

