func (h WorkflowUserGroupsProbeQuery) AndHaving(ps ...workflowgroupmembership.Pred) WorkflowUserGroupsProbeQuery {
	return h.probe(false, ps...)
}

// AndNotHaving adds a NOT EXISTS probe against workflow_group_memberships. This is how
// "has one of these but none of those" is one statement:
//
//	WorkflowUserHavingGroups(q, bought).AndNotHaving(alsoBought)
func (h WorkflowUserGroupsProbeQuery) AndNotHaving(ps ...workflowgroupmembership.Pred) WorkflowUserGroupsProbeQuery {
	return h.probe(true, ps...)
}

func (h WorkflowUserGroupsProbeQuery) probe(neg bool, ps ...workflowgroupmembership.Pred) WorkflowUserGroupsProbeQuery {
	// Copied rather than appended in place: a composer is a value, and
	// two chains branching from one base must not share a backing array.
	p := make([]workflowUserGroupsProbeQueryProbe, len(h.p), len(h.p)+1)
	copy(p, h.p)
	h.p = append(p, workflowUserGroupsProbeQueryProbe{c: workflowgroupmembership.New().Unordered().Where(ps...), neg: neg})
	return h
}

var workflowUserGroupsProbeQueryLowering = func() runtime.Lowering {
	lw := workflowuser.Lowering()
	parentFrag := lw.Frag
	lw.Frag = func(op, col uint32) runtime.Frag {
		if col >= runtime.ChildColBase {
			return workflowgroupmembership.FragOf(op, col-runtime.ChildColBase)
		}
		return parentFrag(op, col)
	}
	// The token's relation id picks the header: 0 positive, 1 negated.
	// Both probes are the same relation, so only the polarity varies.
	lw.Exists = func(rel uint32) string {
		if rel == 1 {
			return "NOT EXISTS (SELECT 1 FROM \"workflow_group_memberships\" AS \"_storm_e\" WHERE \"_storm_e\".\"workflow_user_id\" = \"workflow_users\".\"id\""
		}
		return "EXISTS (SELECT 1 FROM \"workflow_group_memberships\" AS \"_storm_e\" WHERE \"_storm_e\".\"workflow_user_id\" = \"workflow_users\".\"id\""
	}
	return lw
}()

var workflowUserGroupsProbeQueryCache = runtime.NewTreeCache()

func (h WorkflowUserGroupsProbeQuery) stmt(count bool) (*runtime.Stmt, []runtime.Tok) {
	var buf [44]runtime.Tok
	toks := h.q.PredToks(buf[:0])
	stack := 0
	if len(toks) > 0 {
		stack = 1
	}
	for _, pr := range h.p {
		child := pr.c.PredToks(nil)
		toks = runtime.OffsetCols(toks, child, runtime.ChildColBase)
		arity := uint32(0)
		if len(child) > 0 {
			arity = 1 // the child stream reduces to one stack entry
		}
		rel := uint32(0)
		if pr.neg {
			rel = 1
		}
		toks = append(toks, runtime.MakeExists(rel, arity))
		stack++
	}
	if stack > 1 {
		toks = append(toks, runtime.MakeGroup(runtime.KAnd, uint32(stack)))
	}
	if !count {
		toks = h.q.OrderToks(toks)
	}
	sel, cnt, limitSfx := workflowuser.StmtPieces()
	prefix, suffix := sel, limitSfx
	if count {
		prefix, suffix = cnt, ""
	}
	if st := workflowUserGroupsProbeQueryCache.Get(toks); st != nil {
		return st, toks
	}
	return workflowUserGroupsProbeQueryCache.Put(toks, runtime.SpliceTree(prefix, toks, workflowUserGroupsProbeQueryLowering, suffix)), toks
}

// bind returns the arguments in STREAM order: parent predicates, then
// each probe's, then the parent's paging. Each probe takes its own
// binder — bindPreds resets the arenas it fills, so two probes sharing
// one binder would have the second silently overwrite the first.
func (h WorkflowUserGroupsProbeQuery) bind(pb *workflowuser.Binder, paging bool) ([]any, []*workflowgroupmembership.Binder) {
	args := h.q.BindPreds(pb, nil)
	cbs := make([]*workflowgroupmembership.Binder, 0, len(h.p))
	for _, pr := range h.p {
		cb := workflowgroupmembership.GetBinder()
		cbs = append(cbs, cb)
		args = pr.c.BindPreds(cb, args)
	}
	if paging {
		args = h.q.BindPaging(pb, args)
	}
	return args, cbs
}

func (h WorkflowUserGroupsProbeQuery) err() error {
	if err := h.q.Err(); err != nil {
		return err
	}
	for _, pr := range h.p {
		if err := pr.c.Err(); err != nil {
			return err
		}
	}
	return nil
}

// All runs the composed statement.
func (h WorkflowUserGroupsProbeQuery) All(ctx context.Context, ex runtime.Executor) ([]workflowuser.Row, error) {
	if err := h.err(); err != nil {
		return nil, err
	}
	st, _ := h.stmt(false)
	if st.Err != nil {
		return nil, st.Err
	}
	pb := workflowuser.GetBinder()
	defer workflowuser.PutBinder(pb)
	args, cbs := h.bind(pb, true)
	defer func() {
		for _, cb := range cbs {
			workflowgroupmembership.PutBinder(cb)
		}
	}()
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var sl runtime.Slab
	var out []workflowuser.Row
	for rows.Next() {
		out = append(out, workflowuser.Row{})
		if err := workflowuser.Scan(rows.RawValues(), &out[len(out)-1], &sl); err != nil {
			return nil, err
		}
	}
	return out, rows.Err()
}

// Count runs the composed count: no ordering, no paging.
func (h WorkflowUserGroupsProbeQuery) Count(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := h.err(); err != nil {
		return 0, err
	}
	st, _ := h.stmt(true)
	if st.Err != nil {
		return 0, st.Err
	}
	pb := workflowuser.GetBinder()
	defer workflowuser.PutBinder(pb)
	args, cbs := h.bind(pb, false)
	defer func() {
		for _, cb := range cbs {
			workflowgroupmembership.PutBinder(cb)
		}
	}()
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return 0, err
	}
	defer rows.Close()
	if !rows.Next() {
		return 0, rows.Err()
	}
	return runtime.Int8(rows.RawValues()[0]), rows.Err()
}
